#include <pybind11/pybind11.h>
#include <vector>

double compound(const std::vector<double>& r) {
    double v = 1.0;
    for (double x : r) {
        v *= (1.0 + x);
    }
    return v;
}

namespace py = pybind11;
PYBIND11_MODULE(fastmath, m) {
    m.def("compound", &compound, "Compound a vector of simple returns");
}

#include <pybind11/pybind11.h>
#include <pybind11/numpy.h>

double slow_sum(py::array_t<double> arr) {   // borrows the numpy buffer
    auto buf = arr.request();
    double* p = static_cast<double*>(buf.ptr);
    double s = 0.0;
    for (py::ssize_t i = 0; i < buf.size; ++i) {
        s += p[i];
    }
    return s;
}

PYBIND11_MODULE(fastmath, m) {
    m.def("slow_sum", &slow_sum,
          py::call_guard<py::gil_scoped_release>(),
          "Sums a float64 array without holding the GIL");
}

