#include <pybind11/pybind11.h>
#include <pybind11/numpy.h>
#include <cmath>
namespace py = pybind11;

// Takes NumPy arrays in, returns a new NumPy array: ONE boundary crossing for N options
py::array_t<double> price_calls(py::array_t<double> S, py::array_t<double> K,
                                 double r, double sigma, double T) {
    auto Sb = S.unchecked<1>(), Kb = K.unchecked<1>();
    const size_t n = Sb.size();
    py::array_t<double> out(n);
    auto ob = out.mutable_unchecked<1>();
    const double sqrtT = std::sqrt(T);
    for (size_t i = 0; i < n; ++i) {
        const double d1 = (std::log(Sb(i)/Kb(i)) + (r + 0.5*sigma*sigma)*T) / (sigma*sqrtT);
        const double d2 = d1 - sigma*sqrtT;
        // erf-based N(d) (see the numerical lesson for why this form)
        auto N = [](double x){ return 0.5*std::erfc(-x / std::sqrt(2.0)); };
        ob(i) = Sb(i)*N(d1) - Kb(i)*std::exp(-r*T)*N(d2);
    }
    return out;
}

PYBIND11_MODULE(pricer, m) {
    m.def("price_calls", &price_calls, "Batch Black-Scholes calls");
}

