double max_drawdown(const std::vector<double>& equity) {
    double peak = equity.empty() ? 0.0 : equity[0];
    double worst = 0.0;
    for (double px : equity) {
        if (px > peak) peak = px;
        double dd = px / peak - 1.0;
        if (dd < worst) worst = dd;
    }
    return worst;
}

PYBIND11_MODULE(fastmath, m) {
    m.def("max_drawdown", &max_drawdown, "Worst peak-to-trough drawdown");
}
```
Build: `c++ -O3 -shared -std=c++17 -fPIC fastmath.cpp -I$(python3 -c 'import sysconfig; print(sysconfig.get_paths()["include"])') -o fastmath$(python3-config --extension-suffix)`. Verify: `fastmath.max_drawdown([100, 120, 90, 110])` returns $-0.25$ (the trough 90 against the peak 120), matching the numpy reference. Complexity: $O(n)$ time, $O(1)$ extra space.
